def test_reauth_command_merges_scopes() -> None:
    status = ScopeStatus(
        available=True,
        granted_scopes=[
            "email",
            "https://www.googleapis.com/auth/calendar.readonly",
            "https://www.googleapis.com/auth/drive.readonly",
        ],
        missing_required={
            "https://www.googleapis.com/auth/calendar.events": "calendar write",
        },
    )
    cmd = status.reauth_command
    assert "gws auth login --scopes" in cmd
    assert "calendar.events" in cmd
    assert "calendar.readonly" in cmd
    assert "drive.readonly" in cmd
    # Should not include non-https scopes like 'email'
    assert "email" not in cmd.split("--scopes")[1]


